import React from 'react';
import {
  Layers,
  Users,
  Store,
  Briefcase,
  Boxes,
  Calculator,
  GraduationCap,
  BarChart3,
  Code2,
  CalendarClock,
  Compass,
  DollarSign,
  Package,
  Printer,
  Rocket,
  SearchCheck,
  Server,
  Smartphone,
  LifeBuoy,
  ShoppingCart,
  Truck,
  CheckCircle2,
  ShieldCheck,
  HelpCircle,
  Clock,
  Calendar,
  FileText,
} from 'lucide-react';

const ICON_MAP = {
  Layers,
  Users,
  Store,
  Briefcase,
  Boxes,
  Calculator,
  GraduationCap,
  BarChart3,
  Code2,
  CalendarClock,
  Compass,
  DollarSign,
  Package,
  Printer,
  Rocket,
  SearchCheck,
  Server,
  Smartphone,
  LifeBuoy,
  ShoppingCart,
  Truck,
  CheckCircle2,
  ShieldCheck,
  HelpCircle,
  Clock,
  Calendar,
  FileText,
};

export function IconRenderer({ name, size = 20, className = '' }) {
  const IconComponent = ICON_MAP[name] || Layers;
  return <IconComponent size={size} className={className} />;
}
